def ic(nom, cls='', on=False):
    corps = D[nom][1]
    point = '<circle class="pt" cx="19.6" cy="4.4" r="3.1"/>' if on else ''
    return (f'<svg class="ic {cls}{" on" if on else ""}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            f'stroke-width="{2.2 if on else 1.8}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{corps}{point}</svg>')

def orbi(taille=48, etat='repos', cls=''):
    return (f'<svg class="orbi-m {etat} {cls}" width="{taille}" height="{taille}" viewBox="0 0 48 48" aria-hidden="true">'
            '<circle cx="24" cy="24" r="23" fill="#0F3F37"/>'
            '<circle class="orb" cx="24" cy="24" r="13" fill="none" stroke="#A6F26B" stroke-opacity=".45" stroke-width="1.6"/>'
            '<circle cx="24" cy="24" r="5" fill="#F2EDE5"/>'
            '<g class="sat"><circle cx="33.2" cy="14.8" r="4.4" fill="#A6F26B"/></g></svg>')
